package vaultor.linked;
import java.io.*;import java.nio.file.*;import java.util.*;

/** Production ordinary-file policy; deliberately does not enable probe flags. */
public final class LinkedPublicationTests extends SafetyTests {
    static class LinkedFixture implements AutoCloseable {
        final Path dir=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"linked-save-").toAbsolutePath(),root=Files.createDirectory(dir.resolve("root")),journal=dir.resolve("private"),file;
        final LinkedStore store;final String rootCap;final LinkedStore.Opened doc;
        LinkedFixture(String name,String source,LinkedStore.Faults faults)throws Exception{file=root.resolve(name);Files.writeString(file,source);store=new LinkedStore(OWNER,journal,VALIDATOR,CONSENT,List.of(dir.resolve("managed")),faults);rootCap=grant(store,root);doc=store.openRelative(OWNER,rootCap,name);}
        LinkedStore.Receipt save(String local)throws Exception{var result=store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(store,doc,1,local),UUID.randomUUID().toString());if(result.state().equals("RECOVERY_REQUIRED"))System.out.println("RECOVERY "+store.recover(OWNER).stream().filter(r->r.operation().equals(result.operation())).map(r->r.record()==null?r.state():r.record().state()).toList());return result;}
        public void close()throws Exception{store.close();}
    }
    public static void main(String[] args)throws Exception {
        check("ordinary inherited permissions, owner/group, creation and exact source survive production Save",()->{try(var f=new LinkedFixture("guide.md","Base\r\n",null)){String security=MetadataAudit.security(f.file);var creation=Files.readAttributes(f.file,java.nio.file.attribute.BasicFileAttributes.class).creationTime();var result=f.save("Local 😀\r\n");require(result.state().equals("COMMITTED"));require(Files.readString(f.file).equals("Local 😀\r\n"));require(MetadataAudit.security(f.file).equals(security));require(Files.readAttributes(f.file,java.nio.file.attribute.BasicFileAttributes.class).creationTime().equals(creation));require(Files.readString(f.journal.resolve(result.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("ordinary Unicode filename and BOM CRLF source are accepted",()->{try(var f=new LinkedFixture("文档 😀.md","\ufeff# Guide\r\n\r\nBase\r\n",null)){var result=f.save("\ufeff# Guide\r\n\r\nEdited Base\r\n");require(result.state().equals("COMMITTED"));require(Arrays.equals(Files.readAllBytes(f.file),LinkedStore.utf8("\ufeff# Guide\r\n\r\nEdited Base\r\n")));}});
        check("validated no-op preserves original identity and bytes",()->{try(var f=new LinkedFixture("guide.md","Base\n",null)){String id=PublicationCandidates.identity(f.file);var result=f.save("Base\n");require(result.state().equals("COMMITTED"));require(PublicationCandidates.identity(f.file).equals(id));require(!Files.exists(f.journal.resolve(result.operation()).resolve("captured.md")));}});
        check("external content before explicit Save remains conflict and is retained",()->{try(var f=new LinkedFixture("guide.md","Base\n",null)){require(external("write",f.file,"External")==0);require(f.save("Local").state().equals("CONFLICT"));require(Files.readString(f.file).equals("External"));}});
        check("late original hardlink never receives Vaultor content or permission changes",()->{final Path[] file={null},alias={null};final String[] security={null};try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-before-capture")){require(external("hardlink",alias[0],file[0].toString())==0);security[0]=MetadataAudit.security(alias[0]);}})){file[0]=f.file;alias[0]=f.dir.resolve("outside.md");require(f.save("Local").state().equals("COMMITTED"));require(Files.readString(alias[0]).equals("Base\n"));require(MetadataAudit.security(alias[0]).equals(security[0]));require(Files.readString(f.file).equals("Local"));}});
        check("interruption before inheritance restoration never reports successful Save",()->{try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-published"))throw new IOException("INTERRUPTED_METADATA");})){var result=f.save("Local");require(result.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Local"));try(var h=WindowsFiles.lease(f.file,false)){require(WindowsFiles.security(h).protectedDacl());}require(Files.readString(f.journal.resolve(result.operation()).resolve("captured.md")).equals("Base\n"));}});
        check("publication gap occupant is never overwritten by production policy",()->{final Path[] file={null};try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-before-publish"))require(external("create",file[0],"Independent")==0);})){file[0]=f.file;var result=f.save("Local");require(result.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Independent"));}});
        check("postpublication competing replacement is never acknowledged uncontested",()->{final Path[] file={null};try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-finalized"))require(external("replace",file[0],"External newer")==0);})){file[0]=f.file;require(f.save("Local").state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("External newer"));}});
        check("reviewed interrupted permission recovery restores ordinary inheritance without content write",()->{try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-published"))throw new IOException("INTERRUPTED_METADATA");})){String permissions=MetadataAudit.security(f.file);var saved=f.save("Local");var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);var repair=f.store.completeLinkedMetadata(OWNER,review.ticket());require(repair.state().equals("METADATA_RESTORED_REOPEN_REQUIRED"));require(MetadataAudit.security(f.file).equals(permissions));require(Files.readString(f.file).equals("Local"));require(Files.readString(f.journal.resolve(saved.operation()).resolve("captured.md")).equals("Base\n"));}});
        check("metadata recovery refuses a reused pathname even with identical content",()->{try(var f=new LinkedFixture("guide.md","Base\n",(at,op)->{if(at.equals("replacement-published"))throw new IOException("INTERRUPTED_METADATA");})){var saved=f.save("Local");require(external("replace",f.file,"Local")==0);var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);rejects("INDEPENDENT",()->f.store.completeLinkedMetadata(OWNER,review.ticket()));require(Files.readString(f.file).equals("Local"));}});
        check("explicit missing-path restore pins an empty parent against independent out-of-root substitution",()->{final Path[] parent={null},outside={null};try(var f=new LinkedFixture("guide.md","Base",(at,op)->{if(at.equals("replacement-captured"))throw new IOException("INTERRUPTED_CAPTURE");if(at.equals("restore-before-publication"))require(external("move",parent[0],outside[0].toString())!=0);})){parent[0]=Files.createDirectory(f.root.resolve("nested"));outside[0]=f.dir.resolve("escaped");Files.move(f.file,parent[0].resolve("guide.md"));var doc=f.store.openLinked(OWNER,f.rootCap,"nested/guide.md");var saved=f.store.saveLinked(OWNER,doc.document(),doc.epoch(),candidate(f.store,doc,1,"Local"),UUID.randomUUID().toString());require(saved.state().equals("RECOVERY_REQUIRED"));var review=f.store.reviewRecovery(OWNER,saved.operation(),f.rootCap);require(review.state().equals("PATH_MISSING"));require(f.store.restoreMissingBase(OWNER,review.ticket()).state().equals("BASE_RESTORED_REOPEN_REQUIRED"));require(Files.readString(parent[0].resolve("guide.md")).equals("Base"));require(!Files.exists(outside[0]));}});
        Files.createDirectories(Path.of("native/linked-markdown/evidence/production"));Files.writeString(Path.of("native/linked-markdown/evidence/production/publication-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
